import sys
from math import sqrt

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

primes = [p for p in range(2, 1000) if is_prime(p)]
prime_squares = {p**2: p for p in primes}
prime_cubes = {p**3: p for p in primes}

def find_primes(n):
    for p3, prime3 in prime_cubes.items():
        if p3 >= n:
            break
        for p2, prime2 in prime_squares.items():
            if p3 + p2 >= n:
                break
            p1 = n - p3 - p2
            if p1 in prime_squares:
                return f"{prime_squares[p1]} {prime2} {prime3}"
    return "0 0 0"

for line in sys.stdin:
    num = int(line.strip())
    if num == 0:
        break
    print(find_primes(num))
